const params=new URLSearchParams(location.search);let locale=['de','en','ar'].includes(params.get('lang'))?params.get('lang'):demoStore.get('foliquo-demo-locale')||demoStore.get('translateocr-demo-locale')||'en';if(!copy[locale])locale='en';
let step=0,selected=false,spelling='Omar Hassan',changed=false,proposed=false,checks=new Set(),source=true,focus='name';
const t=()=>copy[locale],target=()=>({de:'Deutsch',en:'English',ar:'Arabisch'}[locale]);
function setLocale(value){if(!copy[value])return;locale=value;demoStore.set('foliquo-demo-locale',locale);demoStore.set('translateocr-demo-locale',locale);params.set('lang',locale);history.replaceState(null,'',`${location.pathname}?${params.toString()}${location.hash}`);document.documentElement.lang=locale;document.documentElement.dir=locale==='ar'?'rtl':'ltr';document.title=`foliquo · ${t().title}`;document.querySelector('meta[name="description"]').content=t().description;$('#locale').value=locale;applyStatic();paint();}
function applyStatic(){const x=t();document.querySelector('.demo-return')?.setAttribute('aria-label',locale==='de'?'Seitennavigation':locale==='ar'?'التنقل بين الصفحات':'Page navigation');updateThemeControl();document.querySelector('.skip-link').textContent=locale==='de'?'Zum Arbeitsbereich':locale==='ar'?'انتقل إلى مساحة العمل':'Skip to workspace';document.querySelector('.sidebar-links').setAttribute('aria-label',locale==='de'?'Demo-Navigation':locale==='ar'?'التنقل في العرض':'Demo navigation');document.querySelector('.tabs').setAttribute('aria-label',locale==='de'?'Dokumentansicht':locale==='ar'?'عرض المستند':'Document view');const languageLabel=locale==='de'?'Sprache der Benutzeroberfläche':locale==='ar'?'لغة الواجهة':'Interface language';$('#locale').setAttribute('aria-label',languageLabel);document.querySelector('.language-picker .sr-only').textContent=languageLabel;const publicReturn=['project','projects'].includes(document.body.dataset.return);const returnLabel=publicReturn?(locale==='de'?'Zurück zu den Projekten':locale==='ar'?'العودة إلى المشاريع':'Back to projects'):(locale==='de'?'Zurück zu Foliquo':locale==='ar'?'العودة إلى Foliquo':'Back to Foliquo');const returnUrl=publicReturn?`../../?lang=${locale==='de'?'de':'en'}`:'/';for(const id of ['#back-to-app','#demo-exit']){const link=$(id);if(link){link.textContent=returnLabel;link.href=returnUrl;}}const home=$('#demo-home');if(home){home.href=returnUrl;home.setAttribute('aria-label',returnLabel);}$('#demo-badge').textContent=x.badge;$('#about-link').textContent=x.aboutLink;$('#eyebrow').textContent=x.eyebrow;$('#headline').textContent=x.headline;$('#subhead').textContent=x.subhead;$('#notice').textContent=x.notice;$('#steps').setAttribute('aria-label',locale==='de'?'Demo-Fortschritt':locale==='en'?'Demo progress':'تقدم العرض');document.querySelectorAll('.steps li').forEach((el,i)=>el.querySelector('.step-label').textContent=x.steps[i]);$('#preview-title').textContent=x.original;$('#show-source').textContent=locale==='de'?'Original':locale==='en'?'Original':'الأصل';$('#show-output').textContent=x.translated;$('#about-title').textContent=x.aboutTitle;document.querySelectorAll('.about-grid article').forEach((el,i)=>{el.querySelector('h3').textContent=x.about[i][0];el.querySelector('p').textContent=x.about[i][1];});$('#disclaimer').textContent=x.disclaimer;$('#footer-label').textContent=x.footer;$('#restart').textContent=x.restart;$('#back').textContent=x.back;}
function paint(){const x=t();document.querySelectorAll('[data-step]').forEach(e=>{const i=Number(e.dataset.step);e.classList.toggle('active',i===step);e.classList.toggle('complete',i<step);i===step?e.setAttribute('aria-current','step'):e.removeAttribute('aria-current');});$('#step-title').textContent=x.stepTitles[step];$('#step-count').textContent=locale==='ar'?`${step+1} / 4`:`${step+1} / 4`;$('#back').hidden=step===0;$('#next').hidden=step===3;$('#next').disabled=(step===0&&!selected)||(step===2&&proposed);$('#next').textContent=x.next[step]||'';$('#message').textContent='';const b=$('#step-body');b.replaceChildren();
 if(step===0){b.innerHTML=`<p>${x.docIntro}</p><button id="choose" class="sample-file" type="button" aria-pressed="${selected}"><span class="sample-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 13h8M8 17h5"/></svg></span><span><strong>${x.sample}</strong><small>${x.sides}</small></span><span class="sample-action">${selected?x.selected:x.select}</span></button>`;$('#choose').onclick=()=>{selected=true;paint();$('#message').textContent=x.selected;$('#next').focus();};}
 if(step===1){b.innerHTML=`<p>${x.clarify}</p><p><strong>${x.question}</strong></p><label class="field-choice"><input type="radio" name="spelling" value="Omar Hassan"> ${x.optionA}</label><label class="field-choice"><input type="radio" name="spelling" value="Omar Hasan"> ${x.optionB}</label><p class="muted">${x.spellingNote}</p>`;document.querySelectorAll('[name=spelling]').forEach(e=>{e.checked=e.value===spelling;e.onchange=()=>spelling=e.value;});}
 if(step===2){b.innerHTML=`<p>${x.reviewIntro}</p><button id="prompt" class="secondary">${x.prompt}</button><p class="muted">${x.fixedPrompt}</p><div id="proposal"></div><details class="demo-review-checks"><summary>${locale==='de'?'Prüfliste (optional)':locale==='ar'?'قائمة المراجعة (اختيارية)':'Review checklist (optional)'}</summary><div class="checks">${x.checks.map((c,i)=>`<label><input type="checkbox" data-check="${['name','pages','layout'][i]}"> ${c}</label>`).join('')}</div></details>`;$('#prompt').disabled=changed||proposed;$('#prompt').onclick=()=>{proposed=true;paint();$('#accept').focus();};if(proposed){$('#proposal').innerHTML=`<div class="change"><strong>${x.proposal}</strong><del>Omar Hassan</del><ins>Omar Hasan</ins></div><button class="primary" id="accept">${x.accept}</button>`;$('#accept').onclick=()=>{changed=true;proposed=false;checks.clear();paint();$('#message').textContent=x.messageAccepted;$('#next').focus();};}document.querySelectorAll('[data-check]').forEach(e=>{e.checked=checks.has(e.dataset.check);e.onchange=()=>{e.checked?checks.add(e.dataset.check):checks.delete(e.dataset.check);$('#next').disabled=proposed;};});}
 if(step===3){const fileLocale=locale,v=changed?'final':'initial',base=`assets/${fileLocale}-${v}`;b.innerHTML=`<p>${x.ready}</p><div class="downloads"><a download="Foliquo-${fileLocale}-Demo.zip" href="${base}.zip">${x.bundle}</a><a download="Foliquo-${fileLocale}-Demo.pdf" href="${base}.pdf">${x.pdf}</a><a download="Foliquo-${fileLocale}-Demo.docx" href="${base}.docx">${x.word}</a></div><p class="muted demo-export-note">${x.noCertification}</p>`;}
 paper();}
function paper(){const x=t();$('#preview-title').textContent=source?x.original:x.translated;$('#show-source').classList.toggle('active',source);$('#show-output').classList.toggle('active',!source);$('#show-source').setAttribute('aria-pressed',String(source));$('#show-output').setAttribute('aria-pressed',String(!source));const rows=source?x.rowsOriginal:x.rowsTranslation.map(([id,label,value])=>[id,label,id==='name'&&changed?(locale==='ar'?'عمر حسن (Omar Hasan)':'Omar Hasan'):value]);const paper=$('#paper');paper.dir=(locale==='ar'||source&&locale==='en')?'rtl':'ltr';paper.replaceChildren();const watermark=document.createElement('div');watermark.className='watermark';watermark.textContent=x.watermark;const title=document.createElement('h3');title.textContent=source?x.sourceTitle:x.translationTitle;title.lang=source&&locale==='en'?'ar':locale;title.dir=(locale==='ar'||source&&locale==='en')?'rtl':'ltr';const table=document.createElement('table');for(const[id,label,value]of rows){const tr=document.createElement('tr');tr.classList.toggle('selected',id===focus);tr.tabIndex=0;tr.setAttribute('aria-label',`${label} · ${x.comparison}`);for(const text of [label,value]){const td=document.createElement('td');td.textContent=text;tr.append(td);}const choose=()=>{focus=id;source=!source;paperUpdate();};tr.onclick=choose;tr.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose();}};table.append(tr);}const stamp=document.createElement('div');stamp.className='stamp';stamp.textContent=source?x.stampSource:x.stampTranslation;paper.append(watermark,title,table,stamp);$('#preview-note').textContent=step<2?x.noteBefore:focus==='name'?x.noteName+(changed?'Omar Hasan':'Omar Hassan')+'. '+x.noteOther:x.noteOther;$('#preview-note').dir=locale==='ar'?'rtl':'ltr';}
function paperUpdate(){paper();}
function focusStep(){const title=$('#step-title');title.tabIndex=-1;title.focus({preventScroll:true});if(matchMedia('(max-width:700px)').matches)title.scrollIntoView({block:'start',behavior:'instant'});}
$('#locale').onchange=event=>setLocale(event.target.value);$('#next').onclick=()=>{if(step===1){changed=spelling==='Omar Hasan';source=false;}step=Math.min(3,step+1);paint();focusStep();};$('#back').onclick=()=>{step=Math.max(0,step-1);paint();focusStep();};$('#show-source').onclick=()=>{source=true;paper();};$('#show-output').onclick=()=>{source=false;paper();};$('#restart').onclick=()=>{step=0;selected=false;spelling='Omar Hassan';changed=false;proposed=false;checks.clear();source=true;paint();window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});};
