if(!['light','dark'].includes(demoTheme))demoTheme='dark';
document.documentElement.dataset.theme=demoTheme;
function updateThemeControl(){const button=$('#theme-toggle');const dark=demoTheme==='dark';button.setAttribute('aria-pressed',String(dark));const label=locale==='de'?(dark?'Zum hellen Design wechseln':'Zum dunklen Design wechseln'):locale==='ar'?(dark?'التبديل إلى المظهر الفاتح':'التبديل إلى المظهر الداكن'):(dark?'Switch to light theme':'Switch to dark theme');button.setAttribute('aria-label',label);button.title=label;}
$('#theme-toggle').onclick=()=>{demoTheme=demoTheme==='dark'?'light':'dark';document.documentElement.dataset.theme=demoTheme;demoStore.set('foliquo-demo-theme',demoTheme);updateThemeControl();};
